import json, chess
SAN = "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Qd3 e5 dxe5 Qa5+ Bd2 Qxe5 O-O-O Nxe4 Qd8+ Kxd8 Bg5+ Kc7 Bd8#".split()
b = chess.Board(); U = []; F = [b.fen()]
for s in SAN:
    m = b.parse_san(s); U.append(m.uci()); b.push(m); F.append(b.fen())
assert b.is_checkmate()
FAM = "FAM-FG-RETI-TARTAKOWER"
REF = ("Richard Reti v Savielly Tartakower, Vienna 1910; position before White's move {n} ({m}); move record identical in "
       "Edward Winter's Chess Notes article (chesshistory.com) and a thecharnelhouse.org page (see the lesson sources); "
       "every move replayed with python-chess; position generated by replaying the record")
dec = [(7, "Bd2", 12), (8, "O-O-O", 14), (9, "Qd8+", 16), (10, "Bg5+", 18), (11, "Bd8#", 20)]
positions = []
for k, (n, m, ply) in enumerate(dec, 1):
    positions.append(dict(id=f"PFGretitartakower-{k}", fen=F[ply], family=FAM,
                          provenance=dict(kind="game", ref=REF.format(n=n, m=m), licence="facts (game moves)")))

def item(k, skill, ans, claims, hints, explain, fb=None):
    n, m, ply = dec[k - 1]
    d = dict(id=f"IFGretitartakower-{k}", skill=skill, cue=3, task="find_move", position=f"PFGretitartakower-{k}",
             prompt="White to move. Find the best move.", answer=dict(moves=ans),
             claims=[dict(id=f"C{i+1}", **c) for i, c in enumerate(claims)],
             tags=["node." + skill.rsplit(".D", 1)[0], "tier.4", "cue.3", "kind.game", "family." + FAM, "lang.en", "course.famous-games"],
             hints=hints, explain=explain)
    if fb: d["feedback_by_move"] = fb
    d.update(orientation="white", source=dict(kind="game", id=f"Reti-Tartakower-Vienna-1910-move{n}"),
             review=dict(status="needs-human", reviewer=None))
    return d

def bm(m, st): return dict(type="best_move_in", params=dict(moves=m), statement=st)

